void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen,
                               struct sk_buff *skb, struct rt6_info *rt, bool pmtuprobe) {
    if (!skb) {
        *mtu -= fragheaderlen;
    }

    if (rt->dst.dev && !ipv6_skb_uses_tunnel(skb)) {
        if (skb) {
            *mtu = min(*mtu, rt->dst.dev->mtu);
        } else if (pmtuprobe) {
            *mtu = rt->dst.pmtu;
        }
    }

    *maxfraglen = (*mtu > 0 ? *mtu - fragheaderlen : 0);
}

