        *maxfraglen = *mtu - fragheaderlen;
    }
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen, struct sk_buff *skb, struct rt6_info *rt, bool pmtuprobe) {
    if (!skb) {
        *mtu -= fragheaderlen;
    }

    if (!skb && pmtuprobe) {
        *mtu = rt->dst.dev->mtu - fragheaderlen;
    }

    *maxfraglen = *mtu - fragheaderlen;
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen,
                               unsigned int fragheaderlen,
                               struct sk_buff *skb,
                               struct rt6_info *rt,
                               bool pmtuprobe) {
    if (!rt_is_tunneled(rt)) {
        if (!skb) {
            *mtu -= fragheaderlen;
        } else {
            unsigned int dev_mtu = skb->dev->mtu;
            unsigned int dst_mtu = ip6_skb_mtu(skb);

            if (pmtuprobe) {
                *mtu = min(*mtu, dst_mtu);
            } else {
                *mtu = min(*mtu, dev_mtu);
            }
        }

        *maxfraglen = *mtu - fragheaderlen;
    }
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen, struct sk_buff *skb,
                               struct rt6_info *rt, bool pmtuprobe) {
    if (!rt->dst.dev->type || !strcmp(rt->dst.dev->name, "tunl0")) {
        return;
    }

    if (!skb) {
        *mtu -= fragheaderlen;
    } else {
        if (pmtuprobe) {
            *mtu = min(*mtu, rt->dst.dev->mtu);
        } else {
            *mtu = min(*mtu, rt->dst.path_mtu);
        }
    }

    *maxfraglen = *mtu - fragheaderlen;
}
